import{_ as s,o as n,c as p,b6 as i,lm as e,ln as l,lo as r,lp as t,lq as o,lr as c,ls as h,lt as d,lu as g,lv as m,lw as _,lx as b,ly as f,lz as k,lA as u,lB as S,lC as x,lD as P,lE as A,lF as I,lG as O,lH as w,lI as v,lJ as C,lK as T,lL as y,lM as X,lN as D,lO as M,lP as U,lQ as F,lR as R,lS as N,lT as L,lU as H,lV as q,lW as E,lX as B,lY as V,lZ as j,l_ as z,l$ as $,m0 as Q,m1 as J,m2 as K,m3 as G,m4 as Y}from"./chunks/framework.BUXTSoD9.js";const la=JSON.parse('{"title":"iOS アプリの構築方法 - ネイティブ SwiftUI 開発","description":"","frontmatter":{},"headers":[],"relativePath":"ja-jp/stage-3/cross-platform/ios-app/index.md","filePath":"ja-jp/stage-3/cross-platform/ios-app/index.md"}'),W={name:"ja-jp/stage-3/cross-platform/ios-app/index.md"};function Z(aa,a,sa,na,pa,ia){return n(),p("div",null,[...a[0]||(a[0]=[i('<h1 id="ios-アプリの構築方法-ネイティブ-swiftui-開発" tabindex="-1">iOS アプリの構築方法 - ネイティブ SwiftUI 開発 <a class="header-anchor" href="#ios-アプリの構築方法-ネイティブ-swiftui-開発" aria-label="Permalink to “iOS アプリの構築方法 - ネイティブ SwiftUI 開発”">​</a></h1><h2 id="第1章-ios-アプリと-ios-アプリ開発とは" tabindex="-1">第1章：iOS アプリと iOS アプリ開発とは <a class="header-anchor" href="#第1章-ios-アプリと-ios-アプリ開発とは" aria-label="Permalink to “第1章：iOS アプリと iOS アプリ開発とは”">​</a></h2><p>このチュートリアルでは、完全なクローズドループを完了します：<strong>あなたの頭の中のアイデアから、iPhone に正常にインストールして実行できる実際の iOS アプリまで。</strong></p><p>このチュートリアルでは、少なくとも以下が必要です：</p><ol><li>比較的新しい macOS を実行している Mac</li><li>比較的新しい iOS バージョンを実行し、開発者モードが有効な iPhone</li><li>Xcode が正常にインストールされていること</li><li>Trae がインストールされて開いていること</li><li>使用可能な Apple ID</li></ol><p><img src="'+e+'" alt=""></p><h3 id="_1-1-ios-アプリ" tabindex="-1">1.1 iOS アプリ <a class="header-anchor" href="#_1-1-ios-アプリ" aria-label="Permalink to “1.1 iOS アプリ”">​</a></h3><p>iOS アプリは、iPhone オペレーティングシステム上で実行されるネイティブアプリケーションです。素早く起動し、スムーズに動作し、通知、カメラ、ローカルストレージなどのシステム機能を深く活用できます。</p><p><img src="'+l+'" alt=""></p><h3 id="_1-2-ios-アプリ開発" tabindex="-1">1.2 iOS アプリ開発 <a class="header-anchor" href="#_1-2-ios-アプリ開発" aria-label="Permalink to “1.2 iOS アプリ開発”">​</a></h3><p>核心的には、iOS アプリの構築はいくつかのことしか含みません：</p><ol><li>アプリが解決する問題を明確にする</li><li>ユーザーが見て操作できるインターフェースを設計する</li><li>異なるアクションでのアプリの動作を定義する</li><li>アプリを正しくビルドして iPhone にインストールする</li></ol><h3 id="_1-3-ios-アプリ構築の一般的な方法" tabindex="-1">1.3 iOS アプリ構築の一般的な方法 <a class="header-anchor" href="#_1-3-ios-アプリ構築の一般的な方法" aria-label="Permalink to “1.3 iOS アプリ構築の一般的な方法”">​</a></h3><p>実際の開発では、iOS アプリを構築する方法は1つではありません。ここでは深く掘り下げず、全体的な理解のみを提供します。</p><p>最初の方法は Apple の公式ネイティブアプローチです：Xcode でプロジェクトを作成し、Swift と SwiftUI を使用してインターフェースとロジックを構築します。</p><p><img src="'+r+'" alt=""></p><p>2番目の方法は、React Native や Flutter などのクロスプラットフォームフレームワークを使用し、1つのコードベースを複数のプラットフォームに適応させます。</p><p><img src="'+t+'" alt=""></p><p>上記のアプローチに基づき、このチュートリアルは選択します：<strong>ネイティブ SwiftUI 開発を基盤とし、AI ツールがコーディング作業の大部分を担当します。</strong></p><p><img src="'+o+'" alt=""></p><h3 id="_1-4-このチュートリアルでカバーする-ios-アプリ開発ステップ-概要プレビュー" tabindex="-1">1.4 このチュートリアルでカバーする iOS アプリ開発ステップ（概要プレビュー） <a class="header-anchor" href="#_1-4-このチュートリアルでカバーする-ios-アプリ開発ステップ-概要プレビュー" aria-label="Permalink to “1.4 このチュートリアルでカバーする iOS アプリ開発ステップ（概要プレビュー）”">​</a></h3><p>このチュートリアルで使用するサンプルアプリは <strong>FridgeChef</strong> です。</p><p>ユーザーが冷蔵庫にある食材を入力すると、アプリが実際の AI API を使用して実現可能なレシピを生成し、結果をローカルに保存して後で確認できます。この例は、UI 入力と表示、ネットワークリクエスト、データ解析、ローカルストレージ、実機での最終インストールと実行を含む、実際の iOS アプリケーションの核心部分を完全にカバーしています。</p><p><img src="'+c+'" alt=""></p><ul><li>プロトタイプからネイティブアプリまでの全体的なアイデア</li></ul><p>実装において、このチュートリアルは段階的アプローチを採用します。まず AI を使用して HTML と CSS でインターフェースプロトタイプを素早く生成し、ブラウザでレイアウト構造と情報階層を確認してから、SwiftUI に移行します。</p><ul><li>全体的な開発フローのプレビュー</li></ul><p>全体として、次の章は順番にこれらの段階を経ます：</p><ol><li>基本的な理解の構築 iOS アプリの形態、一般的な開発方法、このサンプルアプリが解決する問題を理解する。</li><li>環境設定の完了 Mac と iPhone を準備し、システムを更新し、Xcode と Trae をインストールし、シミュレーターで正常に実行できる基本的な iOS プロジェクトを作成する。</li><li>本格的な開発の開始 Trae でプロジェクトを開き、AI との対話を通じて段階的に UI と基本的なインタラクションを生成し、アプリを空の殻から使えるものに変える。</li><li>デバッグと整理 コンパイルエラーが現れたり、動作が期待と一致しない場合、AI にトラブルシューティングを手伝わせる。構造が乱雑になったら、AI を使ってリファクタリングして簡素化する。</li><li>実機での実行 署名を設定し、実 iPhone にアプリをインストールし、コードからハードウェアまで1回の完全な検証を完了する。</li></ol><h2 id="第2章-開発環境の準備" tabindex="-1">第2章：開発環境の準備 <a class="header-anchor" href="#第2章-開発環境の準備" aria-label="Permalink to “第2章：開発環境の準備”">​</a></h2><h3 id="_2-1-必要なデバイスとシステム" tabindex="-1">2.1 必要なデバイスとシステム <a class="header-anchor" href="#_2-1-必要なデバイスとシステム" aria-label="Permalink to “2.1 必要なデバイスとシステム”">​</a></h3><p>この実習では、2つのハードウェアが代替不可能です：Mac と iPhone。 同時に、両デバイスは<strong>比較的新しい公式システムバージョン</strong>を実行している必要があります。</p><h4 id="_2-1-1-mac" tabindex="-1">2.1.1 Mac <a class="header-anchor" href="#_2-1-1-mac" aria-label="Permalink to “2.1.1 Mac”">​</a></h4><p>iOS アプリは macOS でのみ開発およびコンパイルできます。これは Apple プラットフォームのハード要件です。</p><p>Xcode が正常にインストールおよび使用できるように、まず macOS を比較的新しい公式バージョンに更新することをお勧めします。<strong>システム設定 -&gt; 一般 -&gt; ソフトウェアアップデート</strong>から確認および更新できます。</p><p><img src="'+h+'" alt=""></p><h4 id="_2-1-2-実際の-iphone-デバイス" tabindex="-1">2.1.2 実際の iPhone デバイス <a class="header-anchor" href="#_2-1-2-実際の-iphone-デバイス" aria-label="Permalink to “2.1.2 実際の iPhone デバイス”">​</a></h4><p>Mac に加えて、このチュートリアルでは実際の iPhone が必要です。アプリが正しくインストールおよび起動できるかを確認するためです。</p><p>デバッグプロセスをスムーズに保つため、iPhone も比較的新しい iOS バージョンを実行している必要があります。<strong>設定 -&gt; 一般 -&gt; ソフトウェアアップデート</strong>から確認および更新できます。</p><p><img src="'+d+'" alt=""></p><p>開発の後半では、この iPhone が実機デバッグのためにケーブルで Mac に接続されます。</p><h4 id="_2-1-3-iphone-で開発者モードを有効にする" tabindex="-1">2.1.3 iPhone で開発者モードを有効にする <a class="header-anchor" href="#_2-1-3-iphone-で開発者モードを有効にする" aria-label="Permalink to “2.1.3 iPhone で開発者モードを有効にする”">​</a></h4><p>Xcode から実機にデバッグアプリをインストールして実行するには、iPhone で開発者モードを有効にする必要があります。</p><p>手順：</p><ol><li><strong>設定</strong>を開く</li><li><strong>プライバシーとセキュリティ</strong>に入る</li><li>一番下までスクロールして<strong>開発者モード</strong>を見つける</li><li>オンにし、指示に従ってデバイスを再起動</li><li>再起動後、デバイスのロックを解除し、開発者モードの有効化を確認</li></ol><p><img src="'+g+'" alt=""></p><p>iPhone が以前に Xcode や他の開発ツールに接続されたことがない場合、<strong>プライバシーとセキュリティ</strong>の下に<strong>開発者モード</strong>が表示されないことがあります。これはシステムの問題ではなく、開発者モードがまだトリガーされていないことを意味します。</p><p>その場合は、次の手順で表示させることができます：</p><ol><li><strong>設定 -&gt; プライバシーとセキュリティ -&gt; 分析と改善</strong>を開く</li><li><strong>App 開発者と共有</strong>をオンにする</li><li>1つ前のレベルに戻り、<strong>プライバシーとセキュリティ</strong>に再び入り、一番下までスクロール</li><li>今度は<strong>開発者モード</strong>が表示されるはずです。有効にしてデバイスを再起動</li></ol><p>上記の手順を完了すると、開発者モードは1度だけ有効にすれば済みます。今後の Xcode を使用した実機デバッグでこの設定を繰り返す必要はありません。</p><p><img src="'+m+'" alt=""></p><h3 id="_2-2-必要なソフトウェア" tabindex="-1">2.2 必要なソフトウェア <a class="header-anchor" href="#_2-2-必要なソフトウェア" aria-label="Permalink to “2.2 必要なソフトウェア”">​</a></h3><p>デバイスとシステムの準備ができた後も、開発に使用するソフトウェアをインストールする必要があります。このチュートリアルは2つのカテゴリのツールのみを使用します：公式 iOS 開発ツールと AI 支援開発ツールです。</p><h4 id="_2-2-1-xcode" tabindex="-1">2.2.1 Xcode <a class="header-anchor" href="#_2-2-1-xcode" aria-label="Permalink to “2.2.1 Xcode”">​</a></h4><p>Xcode は Apple の公式 iOS 開発ツールです。このチュートリアルでは主に、iOS プロジェクトの作成、Swift / SwiftUI コードのコンパイル、シミュレーターまたは実機でのアプリ実行に使用されます。</p><p><img src="'+_+'" alt=""></p><p>Xcode は App Store から直接見つけてインストールできます。インストール後、初めて開くとウェルカム画面が表示されます。以降のプロジェクト作成はそこから始まります。</p><p><img src="'+b+'" alt=""></p><h4 id="_2-2-2-trae" tabindex="-1">2.2.2 Trae <a class="header-anchor" href="#_2-2-2-trae" aria-label="Permalink to “2.2.2 Trae”">​</a></h4><p>Trae はこのチュートリアルで開発作業が行われる主要な環境です。iOS プロジェクト全体を Trae に配置し、AI との対話を通じて開発を完了します。</p><p><img src="'+f+'" alt=""></p><h3 id="_2-3-apple-id-と開発デバッグの注意事項" tabindex="-1">2.3 Apple ID と開発デバッグの注意事項 <a class="header-anchor" href="#_2-3-apple-id-と開発デバッグの注意事項" aria-label="Permalink to “2.3 Apple ID と開発デバッグの注意事項”">​</a></h3><p>iOS プラットフォームでは、アプリを実際のデバイスにインストールするには、開発者署名を経る必要があります。このチュートリアルでは Apple Developer Program のメンバーシップに料金を支払う必要はありません。個人の Apple ID で十分です。</p><h3 id="_2-4-次に進む前のチェックリスト" tabindex="-1">2.4 次に進む前のチェックリスト <a class="header-anchor" href="#_2-4-次に進む前のチェックリスト" aria-label="Permalink to “2.4 次に進む前のチェックリスト”">​</a></h3><p>次の章に入る前に、現在の状態を以下のチェックリストと比較できます。</p><p>すでに以下を持っている必要があります：</p><ol><li>比較的新しい macOS を実行している Mac</li><li>比較的新しい iOS バージョンを実行し、開発者モードが有効な iPhone</li><li>Xcode が正常にインストールされていること</li><li>Trae がインストールされて開いていること</li><li>使用可能な Apple ID</li></ol><p>すべて準備ができていれば、続けて最初の iOS アプリを作成できます。</p><h2 id="第3章-最初の-ios-プロジェクトの作成" tabindex="-1">第3章：最初の iOS プロジェクトの作成 <a class="header-anchor" href="#第3章-最初の-ios-プロジェクトの作成" aria-label="Permalink to “第3章：最初の iOS プロジェクトの作成”">​</a></h2><h3 id="_3-1-xcode-を使用して新規プロジェクトを作成" tabindex="-1">3.1 Xcode を使用して新規プロジェクトを作成 <a class="header-anchor" href="#_3-1-xcode-を使用して新規プロジェクトを作成" aria-label="Permalink to “3.1 Xcode を使用して新規プロジェクトを作成”">​</a></h3><p>Xcode を開きます。ウェルカム画面で、新規プロジェクトの作成を選択します。</p><p><img src="'+k+'" alt=""></p><p><strong>Create new project</strong> をクリックして、プロジェクトテンプレート選択画面に入ります。</p><h3 id="_3-2-アプリテンプレートと技術スタックの選択" tabindex="-1">3.2 アプリテンプレートと技術スタックの選択 <a class="header-anchor" href="#_3-2-アプリテンプレートと技術スタックの選択" aria-label="Permalink to “3.2 アプリテンプレートと技術スタックの選択”">​</a></h3><p>テンプレート選択画面で、以下の設定を使用します：</p><ol><li>プラットフォーム：iOS</li><li>アプリケーションタイプ：App</li></ol><p><img src="'+u+'" alt=""></p><p><strong>Next</strong> をクリックして、プロジェクト情報設定画面に入ります。</p><h3 id="_3-3-プロジェクト情報の設定" tabindex="-1">3.3 プロジェクト情報の設定 <a class="header-anchor" href="#_3-3-プロジェクト情報の設定" aria-label="Permalink to “3.3 プロジェクト情報の設定”">​</a></h3><p>プロジェクト情報画面で、基本設定のみ入力します：</p><ol><li>製品名：アプリ名（例：<code>FridgeChef</code>）</li><li>チーム：個人の Apple ID を選択</li><li>組織識別子：逆ドメイン形式（例：<code>com.example</code>）</li><li>Bundle Identifier：自動生成、デフォルトのまま</li><li>テストシステム：Swift Testing with XCTest UI Tests</li><li>ストレージ：Core Data を選択（後でレシピ履歴を保存するため）</li><li>その他のオプションはデフォルトのまま</li></ol><p><img src="'+S+'" alt=""></p><p><strong>Next</strong> をクリックし、プロジェクトの保存場所を選択します。</p><p><img src="'+x+'" alt=""></p><h3 id="_3-4-作成後のプロジェクト構造の認識" tabindex="-1">3.4 作成後のプロジェクト構造の認識 <a class="header-anchor" href="#_3-4-作成後のプロジェクト構造の認識" aria-label="Permalink to “3.4 作成後のプロジェクト構造の認識”">​</a></h3><p>プロジェクトが作成されると、Xcode が自動的にワークスペースを開きます。この時点では、すべてのファイルを理解する必要はありません。いくつかの主要部分を認識するだけで十分です。</p><p><img src="'+P+'" alt=""></p><p>デフォルトプロジェクトでは、以下が表示されます：</p><ul><li>プロジェクト名の付いたフォルダー</li><li><code>App</code> で終わる Swift ファイル（アプリケーションのエントリーポイント）</li><li><code>ContentView.swift</code> ファイル（デフォルトページ）</li></ul><p>これはすでに実行可能な最小の iOS アプリです。</p><h3 id="_3-5-最初の-ios-アプリの実行" tabindex="-1">3.5 最初の iOS アプリの実行 <a class="header-anchor" href="#_3-5-最初の-ios-アプリの実行" aria-label="Permalink to “3.5 最初の iOS アプリの実行”">​</a></h3><p>コードを変更する前に、元のプロジェクトを直接実行します。</p><p>Xcode の上部ツールバーで、デフォルトの iPhone シミュレーターが選択されたままにし、左上の <strong>Run</strong> ボタンをクリックします。</p><p><img src="'+A+'" alt=""></p><p><img src="'+I+'" alt=""></p><p>すべてが正常であれば、シミュレーターに正常に起動できる空のアプリが表示されます。最初のコンパイルは比較的長い時間がかかる場合があります。以降の章では、まず HTML プロトタイプを使用して待ち時間を短縮します。</p><p><img src="'+O+'" alt=""></p><p>アプリを停止するには、Run ボタンの横の <strong>Stop</strong> をクリックします。</p><h3 id="_3-6-この段階で実際に達成したこと" tabindex="-1">3.6 この段階で実際に達成したこと <a class="header-anchor" href="#_3-6-この段階で実際に達成したこと" aria-label="Permalink to “3.6 この段階で実際に達成したこと”">​</a></h3><p>インターフェースはまだシンプルですが、いくつかの主要な確認を完了しています：</p><ol><li>プロジェクトが正常にコンパイルできる</li><li>シミュレーターがアプリを正しく実行できる</li><li>開発プロセスがエンドツーエンドで機能することが証明された</li></ol><p>これは、今後の問題が主に<strong>コードとロジック自体</strong>に集中することを意味し、環境の問題ではありません。</p><h3 id="_3-7-プロジェクトを-trae-に引き渡す" tabindex="-1">3.7 プロジェクトを Trae に引き渡す <a class="header-anchor" href="#_3-7-プロジェクトを-trae-に引き渡す" aria-label="Permalink to “3.7 プロジェクトを Trae に引き渡す”">​</a></h3><p>次のセクションから、主要な開発作業が徐々に Trae に移行します。</p><p>必要なことはシンプルです：<strong>作成したばかりの iOS プロジェクトフォルダーを Trae で開きます。</strong></p><p><img src="'+w+`" alt=""></p><h2 id="第4章-ai-支援開発の実践-fridgechef-をゼロから構築" tabindex="-1">第4章：AI 支援開発の実践 - FridgeChef をゼロから構築 <a class="header-anchor" href="#第4章-ai-支援開発の実践-fridgechef-をゼロから構築" aria-label="Permalink to “第4章：AI 支援開発の実践 - FridgeChef をゼロから構築”">​</a></h2><p>この章はチュートリアル全体の核心部分です。</p><p>このチュートリアルは「まず SwiftUI を書き、繰り返しコンパイルし、プレビューを調整し続ける」という従来のルートを使用しません。代わりにより効率的なフローを使用します： <strong>まず **<strong>HTML*</strong>* を使用してインターフェース構造を素早く検証し、確認された結果を SwiftUI に移行し、最後に段階的にビジネスロジック、ローカルデータ、インタラクションの詳細を完了します。</strong></p><h3 id="_4-1-ステージ1-要件の明確化" tabindex="-1">4.1 ステージ1：要件の明確化 <a class="header-anchor" href="#_4-1-ステージ1-要件の明確化" aria-label="Permalink to “4.1 ステージ1：要件の明確化”">​</a></h3><p>コードを書く前に、最初のステップはページを構築することではありません — 何を構築するかを明確にすることです。<strong>AI にまず **</strong>プロダクトマネージャー*<strong>* のように振る舞わせ、要件を構造化された仕様書に整理させます。</strong></p><p>Trae のチャットウィンドウに次の指示を入力します。Trae はプロジェクトルートに <code>REQUIREMENTS.md</code> ファイルを生成し、アプリ全体の機能と構造を説明します。</p><p>📋 <strong>コピーするプロンプト：</strong></p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>これから「FridgeChef」という iOS アプリを開発します。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>1. コアコンセプト</span></span>
<span class="line"><span>これは「冷蔵庫に残っている食材で何を料理すればいいかわからない」という問題を解決する AI アシスタントです。</span></span>
<span class="line"><span>ユーザーが現在持っている食材を入力すると、アプリが大規模モデルを呼び出して実用的なレシピを生成します。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>2. コア機能</span></span>
<span class="line"><span>- ホームページ：</span></span>
<span class="line"><span>  目立つ「料理を始める」エントリーを表示し、その下に履歴レシピ記録をカードまたはリスト形式で表示。</span></span>
<span class="line"><span>- 入力ページ：</span></span>
<span class="line"><span>  ユーザーが食材を入力、テキスト入力またはシンプルなクイックタグをサポート。</span></span>
<span class="line"><span>- 結果ページ：</span></span>
<span class="line"><span>  AI 生成のレシピを表示、料理名、食材リスト、調理手順を含む。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>3. 技術要件</span></span>
<span class="line"><span>- SwiftUI を使用</span></span>
<span class="line"><span>- データをローカルに保存（Core Data）</span></span>
<span class="line"><span>- 基本的なページナビゲーションと状態更新をサポート</span></span>
<span class="line"><span></span></span>
<span class="line"><span>プロダクトマネージャーの観点から、これを明確で構造化された REQUIREMENTS.md ドキュメントに整理し、プロジェクトルートに保存してください。</span></span></code></pre></div><p>生成後、ドキュメントをざっと読み、機能ポイントが期待と一致するか確認します。</p><p><img src="`+v+`" alt=""></p><h3 id="_4-2-ステージ2-ビジュアルプロトタイプ" tabindex="-1">4.2 ステージ2：ビジュアルプロトタイプ <a class="header-anchor" href="#_4-2-ステージ2-ビジュアルプロトタイプ" aria-label="Permalink to “4.2 ステージ2：ビジュアルプロトタイプ”">​</a></h3><p>AI に <strong>HTML**</strong> + *<strong>*CSS</strong> を使用して高忠実度のインターフェースプロトタイプを素早く描かせ、全体のレイアウトとスタイルを先に確認します。Trae に引き続き入力します：</p><p>📋 <strong>コピーするプロンプト：</strong></p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>要件が確認されました。</span></span>
<span class="line"><span>HTML + Tailwind CSS を使用して高忠実度のインターフェースプロトタイプを生成してください。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>デザインスタイル：Neo-Pop</span></span>
<span class="line"><span>カラー：</span></span>
<span class="line"><span>- 背景：ライトクリーム #FFFDF5</span></span>
<span class="line"><span>- アクセントカラー：アシッドグリーン #CCFF00、ホットピンク</span></span>
<span class="line"><span></span></span>
<span class="line"><span>視覚的特徴：</span></span>
<span class="line"><span>- 3px の太い黒いボーダー</span></span>
<span class="line"><span>- ぼかしのないハードシャドウ（オフセット 4px）</span></span>
<span class="line"><span>- 大きな丸みを帯びたカード、全体的にステッカー / コミック感</span></span>
<span class="line"><span></span></span>
<span class="line"><span>レイアウト要件：</span></span>
<span class="line"><span>- ホームページは Bento Grid のようなレイアウトを使用</span></span>
<span class="line"><span>- 2つの画面を含む：ホームページと入力ページ</span></span>
<span class="line"><span></span></span>
<span class="line"><span>単一ファイルの index.html を生成し、コンテンツの周囲に iPhone 画面比率をシミュレートしてください。</span></span></code></pre></div><p>生成後、ファイルリストで <code>index.html</code> を見つけ、ブラウザで直接開きます。</p><p><img src="`+C+`" alt=""></p><p>この段階で重要なのは、すべての詳細が完璧かどうかではありません。重要なのは、<strong>ページ構造が合理的か、主要な要素が完全か、全体的な方向が正しいか</strong>です。</p><h3 id="_4-3-ステージ3-ネイティブ再現" tabindex="-1">4.3 ステージ3：ネイティブ再現 <a class="header-anchor" href="#_4-3-ステージ3-ネイティブ再現" aria-label="Permalink to “4.3 ステージ3：ネイティブ再現”">​</a></h3><p>HTML プロトタイプが確定したら、<strong>確認されたインターフェースを SwiftUI に変換します。</strong></p><p>手順：</p><ol><li><code>index.html</code> ファイル（またはブラウザのスクリーンショット）を Trae にアップロード</li><li>AI に基づいて SwiftUI コードを生成するように指示</li></ol><p>📋 <strong>コピーするプロンプト：</strong></p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[index.html アップロード済み]</span></span>
<span class="line"><span></span></span>
<span class="line"><span>この HTML ファイルのレイアウトとスタイルを読んでください。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>タスク：このインターフェースを現在のプロジェクトで SwiftUI を使用して再現してください。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>要件：</span></span>
<span class="line"><span>1. 背景色、太いボーダー、ハードシャドウを含む NeoPopStyle modifier をカプセル化</span></span>
<span class="line"><span>2. ホームレイアウト用の HomeView.swift を作成</span></span>
<span class="line"><span>3. 入力ページ用の InputView.swift を作成</span></span>
<span class="line"><span>4. 今は Mock Data を使用し、Xcode Preview とシミュレーターで正しく表示されることを確認</span></span></code></pre></div><p>完了後、Xcode を開きシミュレーターを実行します。完全な視覚構造を持つ iOS アプリが表示されます。</p><p><img src="`+T+'" alt=""></p><h3 id="_4-4-ステージ4-ai-api-の接続" tabindex="-1">4.4 ステージ4：AI API の接続 <a class="header-anchor" href="#_4-4-ステージ4-ai-api-の接続" aria-label="Permalink to “4.4 ステージ4：AI API の接続”">​</a></h3><p>インターフェースが完了すると、アプリはまだディスプレイ層にすぎません。次に実際の AI 機能を接続する必要があります。このチュートリアルでは <strong>SiliconFlow</strong> が提供する大規模モデルサービスを使用します： <a href="https://cloud.siliconflow.cn/" target="_blank" rel="noreferrer">https://cloud.siliconflow.cn</a></p><p><img src="'+y+'" alt=""></p><p>SiliconFlow は OpenAI API 仕様と互換性のある API を提供しているため、標準的なネットワークリクエストを使用して iOS プロジェクトから便利に呼び出すことができます。</p><p><img src="'+X+'" alt=""></p><p>開始する前に、サイトでアカウントを登録し API Key を作成する必要があります。</p><p><img src="'+D+`" alt=""></p><p>このキーは後続のモデル呼び出しに使用されます。</p><p>📋 <strong>コピーするプロンプト：</strong></p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>AI 機能を接続する必要があります。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>APIService.swift を作成してください。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>設定：</span></span>
<span class="line"><span>- Base URL：https://api.siliconflow.cn/v1</span></span>
<span class="line"><span>- モデル：Qwen/Qwen2.5-7B-Instruct</span></span>
<span class="line"><span>- API Key：今は変数として定義しておいてください。後で記入します</span></span>
<span class="line"><span></span></span>
<span class="line"><span>機能：</span></span>
<span class="line"><span>- generateRecipe(ingredients: [String]) メソッドを書く</span></span>
<span class="line"><span>- System Prompt はモデルに純粋な JSON のみを返すよう厳格に要求する必要がある</span></span>
<span class="line"><span>- JSON フィールドは以下を含む必要がある：dishName, ingredients, steps</span></span>
<span class="line"><span></span></span>
<span class="line"><span>また、返されたデータを解析するための RecipeModel 構造体を定義してください。</span></span></code></pre></div><p>コードが生成された後、<code>APIService.swift</code> に自分のキーを記入します。</p><h3 id="_4-5-ステージ5-core-data-ローカルストレージ" tabindex="-1">4.5 ステージ5：Core Data ローカルストレージ <a class="header-anchor" href="#_4-5-ステージ5-core-data-ローカルストレージ" aria-label="Permalink to “4.5 ステージ5：Core Data ローカルストレージ”">​</a></h3><p>アプリが生成したレシピを記憶させるには、ローカルデータストレージを導入する必要があります。このステージは2つのステップに分かれています。</p><p><strong>ステップ1：Xcode で Core Data を手動設定</strong></p><ol><li><code>FridgeChef.xcdatamodeld</code> を開く</li><li><code>RecipeEntity</code> という名前の新しい Entity を作成</li></ol><p><img src="`+M+'" alt=""></p><ol start="3"><li>以下の属性を追加： <ol><li><p><code>id</code>：<strong>UUID</strong></p></li><li><p><code>name</code>：<strong>String</strong></p></li><li><p><code>cookTime</code>：<strong>String</strong></p></li><li><p><code>difficulty</code>：<strong>String</strong></p></li><li><p><code>desc</code>：<strong>String</strong></p></li><li><p><code>timestamp</code>：<strong>Date</strong></p></li><li><p><code>colorIndex</code>：<strong>Integer 16</strong></p><p><img src="'+U+`" alt=""></p></li></ol></li></ol><p><strong>ステップ2：AI にロジックコードを書かせる</strong></p><p>📋 <strong>コピーするプロンプト：</strong></p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Core Data Entity の設定が完了しました。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Entity：RecipeEntity</span></span>
<span class="line"><span>属性：id, name, difficulty, timestamp, colorindex, cookTime, desc</span></span>
<span class="line"><span></span></span>
<span class="line"><span>以下のタスクを完了してください：</span></span>
<span class="line"><span>1. レシピ生成が成功した後、データを Core Data に保存</span></span>
<span class="line"><span>2. ホームページで FetchRequest を使用して履歴レコードを読み取り、逆時系列順で表示</span></span>
<span class="line"><span>3. データベースが空の場合、フレンドリーな空状態メッセージを表示</span></span></code></pre></div><h3 id="_4-6-ステージ6-アプリアイコンの生成" tabindex="-1">4.6 ステージ6：アプリアイコンの生成 <a class="header-anchor" href="#_4-6-ステージ6-アプリアイコンの生成" aria-label="Permalink to “4.6 ステージ6：アプリアイコンの生成”">​</a></h3><p>最後のステップはアプリに適切なアイコンを準備することです。ここでは <strong>Lovart</strong> を使用してアイコンアセットを生成します：<a href="https://www.lovart.ai/zh" target="_blank" rel="noreferrer">https://www.lovart.ai/zh</a></p><p><img src="`+F+'" alt=""><img src="'+R+`" alt=""></p><p>📋 <strong>Lovart にコピーするプロンプト：</strong></p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>主題：幸せな顔を持つ可愛い擬人化された冷蔵庫キャラクター</span></span>
<span class="line"><span>スタイル：ミニマリストアプリアイコン、Neo-pop スタイル、太い黒いアウトライン、ベクターアート</span></span>
<span class="line"><span>カラー：アシッドグリーン (#CCFF00) とディープブルー</span></span>
<span class="line"><span>背景：ソリッドクリーム色</span></span>
<span class="line"><span>ネガティブプロンプト：テキスト、リアルな詳細、3D レンダー、複雑な背景</span></span></code></pre></div><p>生成後、画像を 1024x1024 にクロップし、Xcode の <code>Assets.xcassets</code> -&gt; <code>AppIcon</code> にドラッグします。</p><p><img src="`+N+'" alt=""></p><p><img src="'+L+'" alt=""></p><p><img src="'+H+'" alt=""></p><p>アプリを再実行すると、完全で認識可能な実際の iOS アプリケーションが表示されます。</p><p><img src="'+q+`" alt=""></p><h3 id="_4-7-ステージ7-高度な体験アップグレード" tabindex="-1">4.7 ステージ7：高度な体験アップグレード <a class="header-anchor" href="#_4-7-ステージ7-高度な体験アップグレード" aria-label="Permalink to “4.7 ステージ7：高度な体験アップグレード”">​</a></h3><p>機能が安定した後、視覚スタイルをさらに改善したい場合、AI に望む効果を説明し、新しいデザイン案を生成させ、確認された結果を SwiftUI に移行するだけです。</p><p>📋 参照プロンプト：</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>アプリの機能はすでに完成していますが、視覚的にインパクトのある UI スタイルを試してみたいです。</span></span>
<span class="line"><span>まず HTML + Tailwind CSS で新しいデザイン案を生成してください。ファイル名は design_v2.html です。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>デザインスタイル：Neo-Pop（ドーパミンスタイル）</span></span>
<span class="line"><span>カラーリクエスト：</span></span>
<span class="line"><span>ディープロイヤルブルーをフルスクリーン背景に使用</span></span>
<span class="line"><span>アシッドグリーン (#CCFF00) をアクセントカラーに使用</span></span>
<span class="line"><span></span></span>
<span class="line"><span>視覚的感覚：</span></span>
<span class="line"><span>すべてのカードに 3px の太い黒いボーダーを使用</span></span>
<span class="line"><span>透明度ぼかしのないハードシャドウを使用、右下にシフト</span></span>
<span class="line"><span></span></span>
<span class="line"><span>レイアウトリクエスト：</span></span>
<span class="line"><span>ホームページ構造を変更せず維持</span></span>
<span class="line"><span>ピル型のボタンと入力ボックスを使用</span></span>
<span class="line"><span></span></span>
<span class="line"><span>ブラウザでプレビューできるように完全なコードを生成してください。</span></span></code></pre></div><p>生成後、この HTML ファイルをブラウザで開きます。</p><p><img src="`+E+`" alt=""></p><p>HTML バージョンが確定したら、iOS プロジェクトの修正を開始できます。</p><p>📋 参照プロンプト：</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[design_v2.html アップロード済み]</span></span>
<span class="line"><span>この HTML の視覚スタイルを分析し、現在の iOS プロジェクトに移行してください。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>タスクリクエスト：</span></span>
<span class="line"><span>新しい NeoPopStyle.swift ファイルを作成</span></span>
<span class="line"><span>neoPopBlue() スタイル modifier をカプセル化</span></span>
<span class="line"><span></span></span>
<span class="line"><span>modifier には以下を含める必要がある：</span></span>
<span class="line"><span>- 丸みを帯びた角</span></span>
<span class="line"><span>- 太い黒いボーダー</span></span>
<span class="line"><span>- 不透明なハードシャドウ</span></span>
<span class="line"><span></span></span>
<span class="line"><span>HomeView をリファクタリング：</span></span>
<span class="line"><span>- 背景をディープロイヤルブルーに変更</span></span>
<span class="line"><span>- プライマリボタンにアシッドグリーンを使用</span></span>
<span class="line"><span>- 履歴レコードカードに白背景を使用</span></span>
<span class="line"><span>- 暗い背景でテキストが明確で読みやすいことを確認</span></span>
<span class="line"><span></span></span>
<span class="line"><span>修正された完全なコードを提供してください。</span></span></code></pre></div><p>Xcode で再度 Run をクリックします。すべてが機能していれば、以下が表示されます：</p><ul><li>機能は以前と全く同じ</li><li>視覚スタイルが大幅に変更</li><li>アプリ全体の品質が明らかにアップグレード</li></ul><p><img src="`+B+'" alt=""></p><h2 id="第5章-実行、デバッグ、エラー処理" tabindex="-1">第5章：実行、デバッグ、エラー処理 <a class="header-anchor" href="#第5章-実行、デバッグ、エラー処理" aria-label="Permalink to “第5章：実行、デバッグ、エラー処理”">​</a></h2><p>前の章でコア機能を完了し、シミュレーターでアプリを正常に実行しました。 しかし iOS アプリにとって、真の完了は「正常にコンパイルされる」ことではありません — <strong>安定した動作と、問題が現れた時の処理方法を知ること</strong>です。</p><h3 id="_5-1-xcode-でアプリを実行" tabindex="-1">5.1 Xcode でアプリを実行 <a class="header-anchor" href="#_5-1-xcode-でアプリを実行" aria-label="Permalink to “5.1 Xcode でアプリを実行”">​</a></h3><p>まず、プロジェクトが Xcode で正しく実行できることを確認します。</p><p>Xcode の左上で、実行デバイスを選択し、デフォルトの iPhone シミュレーターを維持します。<strong>Run</strong> ボタンをクリックしてコンパイルおよび実行します。すべてが正常であれば、アプリがシミュレーターで起動し、第4章で構築したインターフェースが表示されます。</p><h3 id="_5-2-実機でアプリを実行" tabindex="-1">5.2 実機でアプリを実行 <a class="header-anchor" href="#_5-2-実機でアプリを実行" aria-label="Permalink to “5.2 実機でアプリを実行”">​</a></h3><p>ケーブルを使用して iPhone を Mac に接続します。</p><p><img src="'+V+'" alt=""></p><p>初めて接続する際、電話に<strong>このコンピュータを信頼しますか？</strong>と表示されます。信頼をタップし、ロック解除コードを入力します。</p><p><img src="'+j+'" alt=""></p><p>Xcode のデバイスリストで iPhone を選択し、再度 <strong>Run</strong> をクリックします。</p><p>この時点で、電話のホーム画面に <strong>FridgeChef</strong> アイコンが表示され、正常に開いて使用できるはずです。</p><p><img src="'+z+'" alt=""></p><p>このステップは、1つの完全な iOS 開発クローズドループの完了を示します。</p><h3 id="_5-3-ios-開発エラーの一般的な原因" tabindex="-1">5.3 iOS 開発エラーの一般的な原因 <a class="header-anchor" href="#_5-3-ios-開発エラーの一般的な原因" aria-label="Permalink to “5.3 iOS 開発エラーの一般的な原因”">​</a></h3><p>実際の開発では、<strong>エラーに遭遇するのは正常</strong>であり、例外ではありません。</p><p>一般的な問題は通常、以下のカテゴリから発生します：</p><ol><li><strong>コンパイルエラー</strong> Swift 構文、型の不一致、パラメータの欠落など。Xcode は赤色で直接ハイライトします。</li><li><strong>ランタイムエラー</strong> アプリはコンパイルされるが、実行中にクラッシュ — 例：配列の範囲外や nil 値の強制アンラップ。</li><li><strong>権限または設定エラー</strong> ネットワークリクエストがシステムにブロック、Info.plist 設定の欠落、署名の問題など。</li><li><strong>論理エラー</strong> アプリはクラッシュしないが、動作が間違っている — 例：ボタンが応答しない、データが更新されない。</li></ol><p><img src="'+$+'" alt=""></p><p>エラーが現れたら、<strong>エラーメッセージ全体をそのまま Trae のチャットボックスにコピー</strong>するだけです。プロジェクトコンテキストを認識している Trae がデバッグを支援できます。</p><h3 id="_5-4-一般的な実機デバッグエラーと解決方法" tabindex="-1">5.4 一般的な実機デバッグエラーと解決方法 <a class="header-anchor" href="#_5-4-一般的な実機デバッグエラーと解決方法" aria-label="Permalink to “5.4 一般的な実機デバッグエラーと解決方法”">​</a></h3><p>実機デバッグ中のエラーは非常に一般的です。これらの問題は通常、コード自体ではなく、デバイスの信頼、セキュリティルール、または署名設定が原因です。アプリが iPhone でスムーズに実行できない場合、まずこのセクションを確認できます。</p><h4 id="_1-署名と登録の問題" tabindex="-1">1. 署名と登録の問題 <a class="header-anchor" href="#_1-署名と登録の問題" aria-label="Permalink to “1. 署名と登録の問題”">​</a></h4><p><strong>一般的な症状：</strong></p><ul><li>Xcode に次のような赤いエラーが表示される <code>&quot;Communication with Apple failed&quot;</code> または <code>&quot;No profiles for &#39;com.xxx.xxx&#39; were found&quot;</code></li><li>または次のように表示される <code>&quot;Your team has no devices which are compatible&quot;</code></li></ul><p><strong>原因：</strong></p><ul><li>Bundle Identifier が一意でないか無効</li><li>現在の iPhone がまだ開発用 Apple ID に登録されていない</li></ul><p><strong>解決方法：</strong></p><ol><li><strong>Bundle Identifier を変更</strong> Xcode プロジェクト設定で、Bundle Identifier をより一意なものに変更、例： <code>com.yourname.FridgeChef</code></li><li><strong>Xcode に自動的にデバイスを登録させる</strong> エラープロンプトで <code>Try Again</code> または <code>Register Device</code> をクリックし、Xcode にデバイス登録と証明書設定を自動的に完了させる。</li></ol><h4 id="_2-デバイスペアリングと接続の問題" tabindex="-1">2. デバイスペアリングと接続の問題 <a class="header-anchor" href="#_2-デバイスペアリングと接続の問題" aria-label="Permalink to “2. デバイスペアリングと接続の問題”">​</a></h4><p><strong>一般的な症状：</strong></p><ul><li>Xcode に次のように表示される <code>&quot;Device is not available because pairing is in progress&quot;</code></li><li>または次のように表示される <code>&quot;Device Locked&quot;</code></li><li>またはすでに信頼をタップしたのに Xcode がまだスタックしている</li></ul><p><img src="'+Q+'" alt=""></p><p><strong>原因：</strong></p><ul><li>iPhone がまだロックされている</li><li>ペアリングプロセスが完全に完了していない</li><li>Xcode が接続状態を更新していない</li></ul><p><strong>解決方法：</strong></p><ol><li>電話のロックを解除 iPhone がロック解除され、ホーム画面に留まっていることを確認。</li><li>信頼プロセスを完了 電話に<strong>このコンピュータを信頼しますか？</strong>が表示されたら、<strong>信頼</strong>をタップし、<strong>ロック画面のコードを入力</strong>する。</li><li>接続状態を更新 まだスタックしている場合、ケーブルを抜き、2-3秒待って再接続。必要に応じて Xcode を再起動して再試行。</li></ol><h4 id="_3-アプリはインストールされるが開けない" tabindex="-1">3. アプリはインストールされるが開けない <a class="header-anchor" href="#_3-アプリはインストールされるが開けない" aria-label="Permalink to “3. アプリはインストールされるが開けない”">​</a></h4><p><strong>一般的な症状：</strong></p><ul><li>アプリアイコンはすでに iPhone のホーム画面に表示されている</li><li>システムが次のように表示する <strong>信頼されていない開発者</strong></li></ul><p><img src="'+J+'" alt=""></p><p><strong>原因：</strong></p><p>これは iOS のセキュリティメカニズムです。個人の Apple ID でインストールされたデバッグアプリは、手動での信頼認可が必要です。</p><p><strong>解決方法：</strong></p><ol><li><strong>設定</strong>を開く</li><li><strong>一般</strong>に入る</li><li><strong>VPN とデバイス管理</strong>をタップ</li><li><strong>デベロッパ App</strong> の下で Apple ID を見つける</li><li><strong>信頼</strong>をタップし、再度確認</li></ol><p><img src="'+K+'" alt=""></p><p>その後、ホーム画面に戻り、アプリを再度タップします。正常に実行されるはずです。</p><h2 id="第6章-アプリを-app-store-に公開したい場合" tabindex="-1">第6章：アプリを App Store に公開したい場合 <a class="header-anchor" href="#第6章-アプリを-app-store-に公開したい場合" aria-label="Permalink to “第6章：アプリを App Store に公開したい場合”">​</a></h2><p>このチュートリアルで主に完了したのは、<strong>個人の開発およびデバッグバージョンのアプリ</strong>の完全なクローズドループです：プロジェクトの作成、機能の実装、デバッグから、実際のデバイスへの正常なインストールと使用まで。</p><p>さらに進んで、正式に <strong>Apple App Store</strong> にアプリを公開し、すべてのユーザーがダウンロードして使用できるようにしたい場合、より正式なリリースプロセスに入る必要があります。そのプロセスには有料の開発者アカウント、審査ルール、コンプライアンス要件が関係し、このチュートリアルの主要な実践焦点ではないため、以下の内容は<strong>全体的な参照とロードマップ</strong>としてのみ提供されます。</p><p><img src="'+G+'" alt=""></p><blockquote><p>以下の内容は Apple の公式審査要件と公開の経験談（オリジナルの知乎シェアを含む）を参照しています。リンクは以下にリストされています。リンクにアクセスできなくなった場合、タイトルまたはキーワードで検索してオリジナルを見つけることができます。</p></blockquote><h3 id="_6-1-apple-developer-program" tabindex="-1">6.1 Apple Developer Program <a class="header-anchor" href="#_6-1-apple-developer-program" aria-label="Permalink to “6.1 Apple Developer Program”">​</a></h3><p>アプリを App Store に公開するには、Apple の有料開発者プログラムに参加する必要があります：</p><ul><li><strong>Apple Developer Program</strong>（年間 USD $99）</li><li>公式サイト：<a href="https://developer.apple.com/" target="_blank" rel="noreferrer">https://developer.apple.com/</a></li></ul><p>参加後、<strong>App Store Connect</strong> を使用してアプリのエントリを作成し、バージョンを管理し、正式に公開できます。</p><h3 id="_6-2-app-store-connect-アプリエントリの作成" tabindex="-1">6.2 App Store Connect：アプリエントリの作成 <a class="header-anchor" href="#_6-2-app-store-connect-アプリエントリの作成" aria-label="Permalink to “6.2 App Store Connect：アプリエントリの作成”">​</a></h3><p>App Store Connect では、以下を含むがこれに限定されない、完全なアプリレコードを作成する必要があります：</p><ol><li>アプリ名と Bundle ID</li><li>説明、キーワード、プライバシーポリシーリンク</li><li>アプリアイコン、スクリーンショット、プレビュー資料</li><li>価格と配布地域設定</li></ol><p>すべての情報は提出前に完了している必要があります。</p><h3 id="_6-3-ビルドして審査に提出" tabindex="-1">6.3 ビルドして審査に提出 <a class="header-anchor" href="#_6-3-ビルドして審査に提出" aria-label="Permalink to “6.3 ビルドして審査に提出”">​</a></h3><p>メタデータの準備ができたら：</p><ol><li>Xcode で有料開発者アカウントを使用して Release ビルドに署名</li><li>正式バージョンをビルドしてアップロード</li><li>App Store Connect で審査に提出</li></ol><p>提出後、アプリは Apple の審査キューに入ります。審査時間は通常 1-3 日で、ケースによります。</p><h3 id="_6-4-審査ルールと却下の一般的な理由" tabindex="-1">6.4 審査ルールと却下の一般的な理由 <a class="header-anchor" href="#_6-4-審査ルールと却下の一般的な理由" aria-label="Permalink to “6.4 審査ルールと却下の一般的な理由”">​</a></h3><p>Apple は主に以下の観点からアプリを審査します：</p><ul><li>機能と安定性</li><li>プライバシーとデータコンプライアンス</li><li>メタデータと実際の機能の間の一貫性</li><li>権利侵害または誤解を招く行為があるかどうか</li></ul><p>アプリが要件を満たさない場合、審査は却下され、Apple は具体的な理由を提供します。開発者はアプリを修正して再提出する必要があります。</p><h3 id="_6-5-却下された後にすべきこと" tabindex="-1">6.5 却下された後にすべきこと <a class="header-anchor" href="#_6-5-却下された後にすべきこと" aria-label="Permalink to “6.5 却下された後にすべきこと”">​</a></h3><p>アプリが却下された場合：</p><ul><li>フィードバックに従ってコードまたは説明を修正</li><li>バージョンを再提出</li><li>App Store Connect を通じて審査チームとコミュニケーション</li></ul><p>これは公開プロセスの非常に一般的な部分であり、プロジェクトが失敗したことを意味するものではありません。</p><h3 id="参照元" tabindex="-1">参照元 <a class="header-anchor" href="#参照元" aria-label="Permalink to “参照元”">​</a></h3><p>以下の内容は Apple の公式ドキュメントと公開の経験シェアを参照しています：</p><ul><li>App Store 審査ガイドライン（Apple 公式） <a href="https://developer.apple.com/app-store/review/guidelines/?utm_source=chatgpt.com" target="_blank" rel="noreferrer">https://developer.apple.com/app-store/review/guidelines/</a></li><li>審査提出の公式ガイド <a href="https://developer.apple.com/cn/help/app-store-connect/manage-submissions-to-app-review/submit-for-review?utm_source=chatgpt.com" target="_blank" rel="noreferrer">https://developer.apple.com/cn/help/app-store-connect/manage-submissions-to-app-review/submit-for-review</a></li><li>iOS App Store 公開と審査の落とし穴の完全図解ガイド（知乎） <a href="https://zhuanlan.zhihu.com/p/146128612" target="_blank" rel="noreferrer">https://zhuanlan.zhihu.com/p/146128612</a></li></ul><h2 id="第7章-まとめ" tabindex="-1">第7章：まとめ <a class="header-anchor" href="#第7章-まとめ" aria-label="Permalink to “第7章：まとめ”">​</a></h2><p><img src="'+Y+'" alt=""></p><p>おめでとうございます！この時点で、あなたは0から1までの完全な iOS アプリ開発プロセスを自ら歩んできました。環境設定、プロジェクト実行、そして段階的にインターフェース、機能、データ、実機テストを実装するに至るまで、すべての主要な段階が順調に完了しました。さらに重要なのは、Swift 構文を暗記することでここに来たのではなく、実装の大部分を AI に任せたことです。あなたのバックグラウンドが何であれ、このような試みはあなたをより流暢にし、iOS 開発がかつて思われていたほど難しくないことに気づくでしょう。以前は1行のコードも書けなかったとしても、自分自身のアプリを構築できるのです。</p><p>振り返ってみると、全体のプロセスは実際にはそれほど複雑ではありません：構築したいものを決め、HTML でインターフェースを素早くテストし、SwiftUI に変換し、API とローカルデータを接続し、デバッグを1回実行します。これを基盤として、将来的には個人の目覚まし時計、ミニマルな todo リスト、さらにはお気に入りの有名人の口調で話すチャットボットも気軽に構築できます。</p><p>これこそが、このチュートリアル — そして easy-vibe — が教えたい最も重要なことです。未来のバイブコーディングマスターたちの最新の創作物を楽しみにしており、皆さんの作品に目を奪われる日を心待ちにしています。</p>',254)])])}const ra=s(W,[["render",Z]]);export{la as __pageData,ra as default};
